p = 61

# Function to calculate Legendre symbol (a/p)
def legendre(a, p):
    a %= p
    if a == 0:
        return 0
    return pow(a, (p - 1) // 2, p)

# 1. Calculate S2(r)
S2 = {}
for r in range(p):
    if r == 0:
        S2[r] = p + 1 # 62
    else:
        # S2(r) = p - (r/p) since ((-1)/p) = 1
        ls = legendre(r, p)
        S2[r] = p - ls

# 2. Calculate N_c^3(r) (used for D3)
Nc3 = {r: 0 for r in range(p)}
for c in range(p):
    r = pow(c, 3, p)
    Nc3[r] += 1

# 3. Calculate D3(r) = sum_{x=0}^{p-1} Nc3(x) * Nc3(r+x)
D3 = {r: 0 for r in range(p)}
for r in range(p):
    sum_val = 0
    for x in range(p):
        r_plus_x = (r + x) % p
        sum_val += Nc3[x] * Nc3[r_plus_x]
    D3[r] = sum_val

# 4. Calculate Total N = sum_{r=0}^{p-1} S2(r) * D3(r)
Total_N = 0
for r in range(p):
    Total_N += S2[r] * D3[r]

print(f"Total N (Number of solutions): {Total_N}")
print(f"S2(0): {S2[0]}, D3(0): {D3[0]}")
print(f"S2(1): {S2[1]}, D3(1): {D3[1]}")

def is_quadratic_residue(a, p):
    if a == 0:
        return True  # 0 is usually treated separately, but for QRs excluding 0, we check Legendre symbol
    if a % p == 0:
        return True
    return pow(a, (p - 1) // 2, p) == 1

p = 61
Q = []
for a in range(1, p):
    if is_quadratic_residue(a, p):
        Q.append(a)

print(f"Size of Q: {len(Q)}")
print(f"Quadratic Residues (non-zero): {sorted(Q)}")
